template<class T,bool Minimize>
__attribute__((noinline,noipa)) unsigned scalar(const T* data){
 unsigned best=0;
 if(Minimize ? data[best]>data[1] : data[best]<data[1])best=1;
 if(Minimize ? data[best]>data[2] : data[best]<data[2])best=2;
 if(Minimize ? data[best]>data[3] : data[best]<data[3])best=3;
 return best;
}
template<class T,bool Minimize>
__attribute__((noinline,noipa)) unsigned control(const T* data){
 unsigned best=0;
 if(Minimize ? data[best]>data[1] : data[best]<data[1])best=1;
 if(Minimize ? data[best]>data[2] : data[best]<data[2])best=2;
 if(Minimize ? data[best]>data[3] : data[best]<data[3])best=3;
 return best;
}
template<class T,bool Minimize>
__attribute__((noinline,noipa)) unsigned avx2(const T* data){
 const __m256i original=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(data));
 const auto select=[](__m256i a,__m256i b){
  __m256i ca=a,cb=b;
  if constexpr(std::is_unsigned_v<T>){
   const __m256i sign=_mm256_set1_epi64x(std::numeric_limits<std::int64_t>::min());
   ca=_mm256_xor_si256(ca,sign);cb=_mm256_xor_si256(cb,sign);
  }
  const __m256i compare=Minimize?_mm256_cmpgt_epi64(ca,cb):_mm256_cmpgt_epi64(cb,ca);
  return _mm256_blendv_epi8(a,b,compare);
 };
 const __m256i pair=select(original,_mm256_permute4x64_epi64(original,0xb1));
 const __m256i best=select(pair,_mm256_permute4x64_epi64(pair,0x4e));
 const unsigned mask=static_cast<unsigned>(_mm256_movemask_pd(_mm256_castsi256_pd(_mm256_cmpeq_epi64(original,best))));
 return std::countr_zero(mask);
}
volatile std::uint64_t result_sink;
template<class T,bool M>void test(std::size_t count,int distribution,int access){
 std::mt19937_64 rng(20261028+count+distribution*17+access*31);
 std::vector<T> data(count);
 for(T& x:data)x=static_cast<T>(distribution?rng()%8:rng());
 // 符号境界と重複極値も比較する。
 data[0]=std::numeric_limits<T>::min();data[1]=std::numeric_limits<T>::max();data[2]=T{0};data[3]=std::numeric_limits<T>::max();
 constexpr unsigned calls=1U<<19;
 std::vector<std::uint32_t> offsets(calls);
 for(unsigned i=0;i<calls;++i)offsets[i]=static_cast<std::uint32_t>(access?(rng()%(count-3)):((i*4)%(count-3)));
 using F=unsigned(*)(const T*);const std::array<F,3> functions{scalar<T,M>,control<T,M>,avx2<T,M>};
 std::uint64_t expected_sum=0;
 for(auto offset:offsets){
  const T* p=data.data()+offset;T expected=p[0];
  for(int i=1;i<4;++i)expected=M?std::min(expected,p[i]):std::max(expected,p[i]);
  for(auto f:functions){const unsigned selected=f(p);if(selected>=4||p[selected]!=expected)std::abort();}
  expected_sum+=static_cast<std::uint64_t>(expected);
 }
 for(unsigned rep=0;rep<7;++rep){
  for(unsigned j=0;j<3;++j){
   const unsigned variant=(rep+j)%3;const F f=functions[variant];std::uint64_t sum=0;
   const auto start=std::chrono::steady_clock::now();
   for(const auto offset:offsets){const T* p=data.data()+offset;sum+=static_cast<std::uint64_t>(p[f(p)]);}
   const double elapsed=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-start).count()/calls;
   result_sink=sum;if(sum!=expected_sum)std::abort();
   std::printf("%s %d %zu %d %d %u %u %.8f\n",std::is_signed_v<T>?"int64":"uint64",M,count,distribution,access,rep,variant,elapsed);
  }
 }
}
int main(){for(auto n:{std::size_t{32},std::size_t{1}<<20})for(int d=0;d<2;++d)for(int a=0;a<2;++a){test<std::int64_t,true>(n,d,a);test<std::int64_t,false>(n,d,a);test<std::uint64_t,true>(n,d,a);test<std::uint64_t,false>(n,d,a);}}
